import collections
import json
import os
def task_func(directory_path: str) -> dict:
    """
    Count the total appearances of all keys in all JSON files in the specified directory.

    Args:
        directory_path (str): Path to the directory containing JSON files.

    Returns:
        dict: A dictionary with the keys from the JSON files as keys and their counts as values.
    """
    key_counts = collections.Counter()

    # Iterate through all files in the specified directory
    for filename in os.listdir(directory_path):
        # Construct the full file path
        file_path = os.path.join(directory_path, filename)

        # Check if the file is a JSON file
        if os.path.isfile(file_path) and filename.endswith('.json'):
            try:
                # Open and load the JSON file
                with open(file_path, 'r', encoding='utf-8') as json_file:
                    data = json.load(json_file)

                    # Recursively count keys in the JSON data
                    def count_keys(obj):
                        if isinstance(obj, dict):
                            for key in obj:
                                key_counts[key] += 1
                                count_keys(obj[key])
                        elif isinstance(obj, list):
                            for item in obj:
                                count_keys(item)

                    count_keys(data)
            except (json.JSONDecodeError, IOError) as e:
                print(f"Error processing file {filename}: {e}")

    return dict(key_counts)

