import json
import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    """
    Processes a JSON string by:
    1. Removing None values.
    2. Counting the frequency of each unique value.
    3. Replacing all email addresses with the placeholder "None".

    Args:
        json_str (str): A JSON string to process.

    Returns:
        dict: A dictionary containing:
            "data": Processed JSON data.
            "value_counts": A Counter object with the frequency of each unique value.
    """
    def remove_none_values(data):
        """Recursively removes None values from a dictionary or list."""
        if isinstance(data, dict):
            return {k: remove_none_values(v) for k, v in data.items() if v is not None}
        elif isinstance(data, list):
            return [remove_none_values(item) for item in data if item is not None]
        else:
            return data

    def replace_emails(data):
        """Recursively replaces email addresses with the placeholder."""
        if isinstance(data, dict):
            return {k: replace_emails(v) for k, v in data.items()}
        elif isinstance(data, list):
            return [replace_emails(item) for item in data]
        elif isinstance(data, str):
            # Regex to match email addresses
            if re.match(r"[^@]+@[^@]+\.[^@]+", data):
                return REPLACE_NONE
            return data
        else:
            return data

    def flatten(data):
        """Flattens a nested structure into a list of values."""
        if isinstance(data, dict):
            values = []
            for v in data.values():
                values.extend(flatten(v))
            return values
        elif isinstance(data, list):
            values = []
            for item in data:
                values.extend(flatten(item))
            return values
        else:
            return [data]

    # Step 1: Parse the JSON string
    try:
        parsed_data = json.loads(json_str)
    except json.JSONDecodeError:
        raise ValueError("Invalid JSON string")

    # Step 2: Remove None values
    cleaned_data = remove_none_values(parsed_data)

    # Step 3: Replace email addresses with the placeholder
    processed_data = replace_emails(cleaned_data)

    # Step 4: Flatten the data and count the frequency of each unique value
    flattened_values = flatten(processed_data)
    value_counts = Counter(flattened_values)

    # Step 5: Return the result
    return {
        "data": processed_data,
        "value_counts": value_counts
    }
